export type ClipKind = 'wide' | 'reaction' | 'finale';

export interface Clip {
  id: string;
  /** Metro asset: a number on native, `{ uri }` on Expo web. */
  clip: number | { uri: string };
  poster: ImageSourcePropType;
  /** A lifted, face-cropped still for the cut sheet's strip (`<clip>-thumb.jpg`); the poster when none exists. */
  thumb: ImageSourcePropType;
}

