/** Highest n per `<venue>-<kind>`; a missing angle wraps around. */
const COUNTS: Record<string, number> = {
  'arena-finale': 1,
  'arena-reaction': 2,
  'arena-wide': 2,
  'club-finale': 1,
  'club-reaction': 2,
  'club-wide': 2,
  'openmic-finale': 1,
  'openmic-reaction': 2,
  'openmic-wide': 2,
  'poetry-reaction': 1,
  'singing-reaction': 1,
  'singing-wide': 1,
  'theatre-finale': 1,
  'theatre-reaction': 2,
  'theatre-wide': 2,
};

export const CLIP_IDS = Object.keys(clips);

/** How many angles exist for `<venue>-<kind>` (0 when none). */
export function clipCount(venue: string, kind: ClipKind): number {
  return COUNTS[`${venue}-${kind}`] || 0;
}

/** The clip for a venue (`singing` for the singing act), kind and 1-based angle; undefined when none exists (use the still plate). */
export function clipFor(venue: string, kind: ClipKind, n: number): Clip | undefined {
  const count = COUNTS[`${venue}-${kind}`] || 0;
  if (!count) return undefined;
  const i = ((Math.max(1, Math.floor(n)) - 1) % count) + 1;
  return clips[`${venue}-${kind}-${i}`];
}
